<?php require __DIR__ . '/../partials/header.php'; ?>
<div class="card"><div class="card-header"><h1>My Orders</h1><p>Your order history — latest first.</p></div><?php if(!$orders):?><p class="muted">No orders yet.</p><?php else:?><?php foreach($orders as $o):?><div style="border:1px solid #dddbd4;border-radius:12px;padding:14px;margin-bottom:12px;background:#fff;"><div><strong>Order #<?php echo e($o['id']);?></strong> <span class="small muted" style="float:right;"><?php echo e($o['created_at']);?></span></div><div>Total: <strong>TK <?php echo e(number_format((float)$o['total_amount'],2));?></strong> &nbsp; Status: <strong><?php echo e($o['delivery_status']);?></strong></div><?php if($o['items']):?><table class="data-table" style="margin-top:10px;"><tr><th>Product</th><th>Qty</th><th>Price</th><th>Subtotal</th></tr><?php foreach($o['items'] as $it):?><tr><td><?php echo e($it['name']);?></td><td><?php echo e($it['qty']);?></td><td>TK <?php echo e(number_format((float)$it['price'],2));?></td><td>TK <?php echo e(number_format((float)$it['price']*(int)$it['qty'],2));?></td></tr><?php endforeach;?></table><?php endif;?></div><?php endforeach;?><?php endif;?></div>
